var options = {
	cellSize: 10
}

var s = {
	width: 0,
	height: 0,
	frameRate: 30,
	cols: 0,
	rows: 0
}

var d = {
	frameRate
}

var canvas;
var context;

window.onload = function(){setup()};

function setup() {

	canvas = document.getElementsByTagName('canvas')[0];
	context = canvas.getContext('2d');

	s.width = window.innerWidth;
	s.height = window.innerHeight;

	canvas.width = s.width - (s.width % s) + 1;
	canvas.height = s.height - (s.height % s) + 1;

	cols = (s.width - 1) / options.cellSize;
	rows = (s.height - 1) / options.cellSize;

}